<?php $title='Staff Users';require __DIR__.'/includes/header.php';require_admin();$rows=db()->query('SELECT * FROM users ORDER BY created_at DESC')->fetchAll();?><div class="page-head"><div><h1>Staff users</h1><p class="muted">Manage access to the notary system.</p></div><a class="btn" href="user_add.php">+ Add user</a></div><div class="card table-wrap"><table class="table"><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><?=e(ucfirst($r['role']))?></td><td><span class="badge <?=$r['status']==='active'?'paid':'pending'?>"><?=e(ucfirst($r['status']))?></span></td><td><div class="actions"><a class="btn light" href="user_edit.php?id=<?=$r['id']?>">Edit</a><?php if((int)$r['id']!==(int)$user['id']):?><form method="post" action="user_delete.php" onsubmit="return confirm('Delete this user?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/includes/footer.php';
